      ["Support planning should be individualised to communication, daily living and participation needs.",true,"Care aims to maximise function and inclusion."],
      ["Challenging behaviour should prompt assessment for pain, illness, communication needs and environmental triggers.",true,"Behaviour may communicate unmet needs or distress."],
      ["An IQ score alone fully describes a person's support needs.",false,"Adaptive functioning and context are also essential."],
      ["Family support and accessible education can improve participation and independence.",true,"Appropriate support promotes inclusion and skills."]
