    sba:[
      {title:"Behaviour change",category:"Intellectual Disability and Learning Disorders",stem:"A minimally verbal young person with intellectual disability suddenly becomes distressed and aggressive. What should be done first?",options:{A:"Assume the behaviour is intentional",B:"Look for pain, illness, communication barriers and environmental triggers",C:"Use punishment only",D:"Ignore the change",E:"Start sedatives before assessment"},answer:"B",explanation:"New behaviour change requires assessment for unmet needs and medical causes."},
      {title:"Assessment",category:"Intellectual Disability and Learning Disorders",stem:"Which is needed alongside intellectual testing when assessing intellectual disability?",options:{A:"Adaptive functioning",B:"Favourite sport",C:"Clothing preference",D:"Eye colour",E:"Hand dominance only"},answer:"A",explanation:"Adaptive functioning across conceptual, social and practical domains is essential."},
      {title:"Learning disorder",category:"Intellectual Disability and Learning Disorders",stem:"A school-aged child has persistent reading difficulties despite appropriate teaching. What is appropriate?",options:{A:"Assess learning, development, sensory factors and educational context",B:"Assume laziness",C:"Remove all school support",D:"Diagnose dementia",E:"Ignore developmental history"},answer:"A",explanation:"A comprehensive assessment considers learning, development, sensory function and educational opportunity."}
    ],
    essays:[{title:"Intellectual disability",category:"Intellectual Disability and Learning Disorders",prompt:"Outline assessment and support planning for a child with suspected intellectual disability.",max:20,modelAnswer:"Take developmental, medical, family and educational history; assess intellectual and adaptive functioning using appropriate methods; evaluate communication, sensory, physical and mental health needs; assess safeguarding and family support. Formulate individual strengths and needs. Coordinate paediatric, psychological, educational and social services, create practical goals for communication and daily living, and review transition and caregiver support.",rubric:[{label:"Developmental and functional assessment",points:5,feedback:"Include developmental history, intellectual and adaptive functioning.",groups:[["developmental","history"],["intellectual","adaptive"],["daily living","function"]]}, {label:"Health and safeguarding",points:5,feedback:"Assess physical, sensory, mental health and safety needs.",groups:[["physical","sensory"],["mental health","medical"],["safeguarding","safety"]]}, {label:"Individualised plan",points:5,feedback:"Set practical communication, learning and independence goals.",groups:[["individualised","strengths"],["communication","learning"],["independence","daily living"]]}, {label:"Multidisciplinary and family support",points:5,feedback:"Coordinate education, health and social care and support caregivers.",groups:[["multidisciplinary","education"],["family","caregiver"],["review","transition"]]}]}]
