    sba:[
      {title:"Capacity",category:"Forensic Psychiatry, Ethics and Mental Health Law",stem:"A patient makes a decision clinicians consider unwise. What is the correct principle?",options:{A:"Unwise decision automatically means incapacity",B:"Assess capacity for that specific decision using applicable criteria",C:"Family decides automatically",D:"Diagnosis alone proves incapacity",E:"Do not explain options"},answer:"B",explanation:"Capacity is decision-specific; an unwise choice alone does not establish incapacity."},
      {title:"Confidentiality",category:"Forensic Psychiatry, Ethics and Mental Health Law",stem:"A patient discloses a serious, credible threat toward an identifiable person. What should the clinician do?",options:{A:"Ignore it absolutely",B:"Assess risk urgently and follow applicable legal/professional disclosure procedures",C:"Post details publicly",D:"Promise secrecy without qualification",E:"Avoid documenting"},answer:"B",explanation:"Urgent risk assessment and local legal/professional guidance are needed."},
      {title:"Mental health law",category:"Forensic Psychiatry, Ethics and Mental Health Law",stem:"Which principle should guide compulsory psychiatric care?",options:{A:"Follow local law, use the least restrictive appropriate option and document safeguards",B:"Use compulsion for convenience",C:"Ignore review rights",D:"Avoid explaining decisions",E:"Use the same rules in every jurisdiction"},answer:"A",explanation:"Compulsory care must meet local legal criteria and procedural safeguards."}
    ],
    essays:[{title:"Capacity and confidentiality",category:"Forensic Psychiatry, Ethics and Mental Health Law",prompt:"Discuss how a clinician should approach a difficult capacity or confidentiality decision in psychiatry.",max:20,modelAnswer:"Clarify the specific decision, relevant information and immediate risks. Presume and support capacity according to applicable law; assess whether the person can understand, retain, use/weigh information and communicate a choice where these are the relevant local criteria. Explain confidentiality and its limits, consider consent and proportionality, consult senior/legal guidance when needed, document reasoning and follow local statutory procedures and review rights.",rubric:[{label:"Decision and capacity assessment",points:5,feedback:"Define the specific decision, support participation and apply local capacity criteria.",groups:[["specific decision","decision"],["support","participation"],["understand","weigh"]]}, {label:"Risk and confidentiality",points:5,feedback:"Assess risk, consent, confidentiality limits and proportionality.",groups:[["risk","safety"],["confidentiality","consent"],["proportionate","disclosure"]]}, {label:"Legal/professional process",points:5,feedback:"Follow local law, consult when needed and respect safeguards.",groups:[["local law","legal"],["senior","consult"],["safeguards","review"]]}, {label:"Documentation and communication",points:5,feedback:"Explain decision, document rationale and communicate with relevant parties appropriately.",groups:[["document","rationale"],["explain","communication"],["relevant","follow up"]]}]}]
