/* Expanded module banks: original practice questions aligned to the uploaded psychiatry topic taxonomy. */
(()=>{
const configs={"foundations":{"label":"Foundations: History, MSE and Psychopathology","themes":["Structured psychiatric history and mental state examination","Psychopathology: delusions, hallucinations and thought disorder","Cognition, capacity and collateral history","Biopsychosocial formulation and initial management"],"facts":[["Open questions help patients describe concerns in their own words.","Open questions should always be avoided in psychiatric interviews.","They encourage a patient-led initial narrative."],["A hallucination is a perception-like experience without a corresponding external stimulus.","A hallucination always requires an external stimulus.","The defining feature is perception without the corresponding stimulus."],["A delusion is a fixed belief not ordinarily corrected by contrary evidence.","A delusion is any unusual belief that is readily changed by evidence.","Fixedness and resistance to counter-evidence distinguish delusions from ordinary beliefs."],["The mental state examination describes the patient's current presentation.","The mental state examination replaces the longitudinal history.","The MSE is a current-state snapshot and complements history."],["Collateral history can clarify onset, change from baseline and risk.","Collateral history is never useful in a psychiatric assessment.","With appropriate consent and confidentiality, collateral can be important."],["Capacity is decision-specific and may fluctuate over time.","Capacity is determined solely by whether a person agrees with the clinician.","Capacity concerns a particular decision at a particular time."],["A formulation integrates biological, psychological and social factors.","A formulation is simply a list of diagnostic labels.","Formulation explains how factors may contribute to the presentation."],["Risk assessment should consider history, current state and protective factors.","A denial of suicidal thoughts means no further risk assessment is needed.","Risk assessment is broader than a single question."],["Thought insertion describes an experience that thoughts are put into one's mind by an external agent.","Thought insertion means a person believes others can hear their thoughts.","Insertion concerns the perceived external placement of thoughts."],["Orientation, attention, memory and executive function may be assessed when indicated.","Cognitive assessment is unnecessary whenever a patient has a psychiatric diagnosis.","Cognition can reveal delirium, neurocognitive disorders and other contributors."]]},"mood":{"label":"Mood Disorders and Suicide Risk","themes":["Assessment and management of depressive episode","Bipolar screening and differential diagnosis","Suicide-risk assessment and safety planning","Treatment-resistant or psychotic mood disorder"],"facts":[["Past mania or hypomania should be explored before treating depression.","Bipolar history is irrelevant when a patient presents with depression.","Past elevated mood can change diagnosis and treatment."],["Anhedonia is a loss of interest or pleasure.","Anhedonia means increased energy and goal-directed activity.","Anhedonia is a core depressive symptom."],["Suicide-risk assessment explores thoughts, intent, plans, means and protective factors.","A patient denying suicidal thoughts means risk assessment can stop.","Risk is dynamic and requires a broader assessment."],["Psychotic symptoms in severe depression warrant urgent specialist assessment.","Psychotic depression can always be managed without considering severity or safety.","Psychosis and severity affect urgency and treatment setting."],["Functioning and duration help establish the clinical significance of mood symptoms.","Symptom duration and functional impairment are never relevant.","Diagnosis requires a careful assessment of course and impact."],["Mania may involve elevated or irritable mood with increased energy and reduced need for sleep.","A reduced need for sleep in mania always causes daytime exhaustion.","Reduced need for sleep is distinct from insomnia with fatigue."],["Treatment choices should consider comorbidity, interactions and overdose safety.","Medication choice should ignore overdose toxicity and interactions.","Safe prescribing considers individual risk and medical context."],["A safety plan should identify warning signs, coping steps and sources of help.","Safety planning consists only of telling a patient to promise not to self-harm.","Collaborative safety planning is practical and specific."],["Mixed features can include depressive symptoms occurring alongside manic symptoms.","Mania and depression can never occur with overlapping symptoms.","Mixed presentations require careful assessment and risk review."],["Follow-up should be closer when symptoms, treatment changes or risks are unstable.","Follow-up frequency should never change with clinical risk.","Monitoring should reflect severity and changing circumstances."]]},"psychosis":{"label":"Schizophrenia and Psychotic Disorders","themes":["First-episode psychosis assessment and differential","Long-term schizophrenia management and relapse prevention","Antipsychotic adverse effects and monitoring","Psychosis with risk, substance use or medical causes"],"facts":[["Psychosis assessment includes substance, medication and medical causes.","Every psychotic presentation is automatically schizophrenia.","Psychosis has a broad differential diagnosis."],["A delusion is a belief held with strong conviction despite contrary evidence.","A delusion is simply any culturally shared belief.","Context, conviction and cultural setting matter."],["Auditory hallucinations can occur in psychotic disorders but are not diagnostic alone.","Auditory hallucinations alone prove schizophrenia.","Diagnosis requires symptoms, course and differential assessment."],["Negative symptoms may include avolition, reduced expression and social withdrawal.","Negative symptoms refer only to hallucinations and delusions.","Negative symptoms involve reductions in normal functions."],["Antipsychotic choice should consider metabolic, neurological and cardiovascular risks.","Antipsychotics require no physical-health monitoring.","Monitoring helps identify important adverse effects."],["Early warning signs and adherence planning can support relapse prevention.","Relapse prevention has no role after symptoms improve.","Ongoing care and early intervention can reduce relapse impact."],["Catatonia requires prompt recognition and urgent clinical assessment.","Catatonia is always harmless and needs no urgent assessment.","Catatonia may be medically dangerous."],["Substance-induced psychosis should be considered when the history supports it.","Substance exposure can never cause psychotic symptoms.","Intoxication or withdrawal can contribute to psychosis."],["Suicide and vulnerability risks should be assessed in psychosis.","Risk assessment is unnecessary if the patient is calm during interview.","Risk depends on history, symptoms, context and supports."],["Shared decision-making can improve engagement with ongoing treatment.","A patient’s preferences should never be considered in treatment planning.","Preferences and goals should inform care where possible."]]},"anxiety-ocd":{"label":"Anxiety, OCD and Related Disorders","themes":["Assessment and management of panic and anxiety disorders","OCD assessment and exposure-based treatment","Phobias and avoidance behaviour","Differential diagnosis and functional impairment"],"facts":[["Panic attacks can include sudden intense fear and autonomic symptoms.","Panic attacks always indicate an acute cardiac event.","Panic symptoms need appropriate medical and psychiatric assessment."],["OCD involves obsessions, compulsions or both that cause distress or impairment.","OCD is simply a preference for tidiness.","OCD is defined by intrusive thoughts and/or repetitive behaviours."],["Exposure and response prevention is an evidence-based treatment for OCD.","Compulsions should always be encouraged to remove anxiety permanently.","ERP targets avoidance and compulsive responses."],["Anxiety assessment should consider substances, medication and physical illness.","Physical causes never need consideration in anxiety symptoms.","Differential diagnosis includes relevant medical and substance factors."],["Avoidance can maintain phobic anxiety over time.","Avoidance invariably cures a phobia in the long term.","Avoidance can prevent corrective learning."],["CBT can help patients identify and test unhelpful patterns of thinking and behaviour.","CBT requires the clinician to dismiss the patient’s distress.","CBT is collaborative and structured."],["Severity and functional impairment guide treatment planning.","Treatment should be identical regardless of severity or impairment.","Care should be matched to needs and impact."],["OCD obsessions are typically intrusive and unwanted.","Obsessions are always pleasurable and voluntarily chosen.","Obsessions are commonly distressing and intrusive."],["Benzodiazepines require caution because of sedation, dependence and withdrawal risks.","Benzodiazepines have no dependence or sedation risks.","These risks influence duration and prescribing."],["Assessment should include depression, self-harm and suicide risk when indicated.","Anxiety disorders exclude the possibility of depression or suicide risk.","Comorbidity and risk should be assessed when relevant."]]},"stress-somatoform":{"label":"Stress, Somatic and Dissociative Disorders","themes":["PTSD and trauma-informed assessment","Acute stress and adjustment presentations","Somatic symptom and health anxiety presentations","Dissociation, safety and integrated management"],"facts":[["PTSD may include re-experiencing, avoidance and heightened threat responses.","PTSD requires that the person never experiences intrusive memories.","Re-experiencing is one possible core symptom domain."],["Trauma-informed care prioritises safety, choice and collaboration.","Trauma-informed care requires forcing detailed disclosure at the first visit.","Patients should not be pressured to recount trauma before they are ready."],["Somatic symptom presentations involve distressing symptoms and disproportionate related thoughts or behaviours.","Physical symptoms should be dismissed as fabricated whenever tests are normal.","Symptoms are real experiences and require respectful assessment."],["Dissociation can involve disruptions in memory, identity, awareness or perception.","Dissociation always means deliberate deception.","Dissociative symptoms are not synonymous with malingering."],["Assessment should consider medical causes alongside psychological factors.","A psychological formulation means physical assessment is never needed.","Physical and psychological explanations can coexist."],["Grounding strategies may help some patients manage dissociative distress.","Grounding always worsens dissociation and must be avoided.","Grounding can support present-moment orientation for some patients."],["Adjustment disorder is linked to an identifiable stressor and clinically significant distress or impairment.","Adjustment disorder occurs only in the absence of any stressor.","The stressor and its relationship to symptoms are central."],["PTSD treatment may include trauma-focused psychological therapies when appropriate.","Trauma-focused therapy is never used for PTSD.","Evidence-based trauma-focused approaches may be indicated."],["Risk assessment should include self-harm, suicide, substance use and safeguarding where relevant.","Trauma history means suicide-risk assessment is unnecessary.","Risk must be assessed individually."],["Continuity and coordinated care can reduce fragmented investigations and treatment.","Repeated uncoordinated investigations are always the best long-term plan.","A coherent, validating care plan is usually preferable."]]},"substances":{"label":"Alcohol and Substance Use Disorders","themes":["Alcohol intoxication, withdrawal and complications","Substance-use assessment and motivational intervention","Opioid or sedative overdose and withdrawal","Relapse prevention and harm reduction"],"facts":[["Alcohol withdrawal can cause seizures and delirium tremens.","Alcohol withdrawal is always benign and needs no monitoring.","Severe withdrawal can be life-threatening."],["A substance-use assessment should explore pattern, harms, dependence and readiness to change.","The amount used is the only relevant part of substance assessment.","Context, consequences and dependence features also matter."],["Opioid overdose may cause respiratory depression and reduced consciousness.","Pinpoint pupils alone are required to recognise opioid toxicity.","Clinical recognition includes breathing and consciousness, not one sign alone."],["Motivational interviewing explores ambivalence without confrontation.","Motivational interviewing relies on shaming the patient into abstinence.","A collaborative style can support change."],["Thiamine is important in patients at risk of alcohol-related deficiency.","Thiamine has no role in preventing alcohol-related neurological complications.","Thiamine is used where deficiency risk is significant."],["Withdrawal management should be guided by substance, severity and clinical setting.","All substances have identical withdrawal syndromes and treatments.","Withdrawal risks and treatment differ by substance."],["Harm reduction can improve safety even when immediate abstinence is not achieved.","Care should be withheld unless the patient promises abstinence.","Harm reduction is a pragmatic component of care."],["Relapse prevention can include trigger identification, support and ongoing treatment.","A lapse proves that further treatment cannot help.","Relapse is a signal to reassess and strengthen support."],["Screening should be non-judgmental and confidential within appropriate limits.","Substance-use questions should always be asked in a punitive manner.","Respectful inquiry supports disclosure and engagement."],["Polysubstance use can increase toxicity and complicate withdrawal.","Combining sedatives and alcohol is reliably safe.","Combined depressants can increase risk."]]},"personality":{"label":"Personality and Impulse Control Disorders","themes":["Personality-disorder assessment and formulation","Self-harm, emotional dysregulation and safety planning","Therapeutic boundaries and psychological treatment","Impulse-control presentations and comorbidity"],"facts":[["Personality-disorder assessment considers enduring patterns across contexts and time.","A single difficult interaction is sufficient to diagnose a personality disorder.","Diagnosis requires a broader longitudinal pattern."],["Self-harm should be assessed compassionately for function, intent and immediate safety.","Self-harm should be dismissed as attention-seeking without assessment.","Every episode deserves a respectful, individual assessment."],["A collaborative safety plan can identify triggers, coping and support contacts.","A no-harm contract alone reliably eliminates suicide risk.","Safety planning is more useful than relying on a promise alone."],["DBT may be helpful for recurrent self-harm and emotional dysregulation in appropriate patients.","Psychological therapies have no role in emotional dysregulation.","Structured therapies can target coping and interpersonal skills."],["Consistent professional boundaries support a safe therapeutic relationship.","Inconsistent boundaries always improve treatment outcomes.","Consistency helps maintain clarity and trust."],["Comorbid depression, PTSD and substance use should be assessed.","Personality-disorder presentations exclude other mental disorders.","Comorbidity is common and affects care planning."],["Risk formulation should include triggers, patterns, strengths and protective factors.","Risk can be accurately summarised by one score alone.","Structured tools may support but do not replace formulation."],["Stigma and pejorative language can harm engagement.","Stigmatising labels improve therapeutic alliance.","Respectful, person-centred language supports care."],["Treatment planning should be collaborative and realistic.","Patients should be excluded from decisions about their goals.","Shared goals can improve engagement."],["Impulsivity may increase risk in some clinical contexts and requires individual assessment.","Impulsivity always means a person is violent.","Impulsivity has varied presentations and does not predict violence by itself."]]},"child-adolescent":{"label":"Child and Adolescent Psychiatry","themes":["Autism and ADHD assessment","Emotional and behavioural presentations in children","Safeguarding, developmental history and family collaboration","Child mental-health treatment and school liaison"],"facts":[["Developmental assessment considers milestones, functioning and context across settings.","A single behaviour in one setting is enough to diagnose ADHD.","Symptoms, impairment and cross-setting information are important."],["Autism assessment considers social communication and restricted or repetitive patterns.","Autism is caused by poor parenting.","Autism is a neurodevelopmental condition and is not caused by poor parenting."],["ADHD symptoms should be developmentally inappropriate, persistent and impairing.","Normal age-related activity alone proves ADHD.","Development, duration, impairment and multiple settings matter."],["Safeguarding concerns require timely action according to local procedures.","Confidentiality means a child-protection concern must never be shared.","Safety duties may require appropriate information sharing."],["Parents, carers, school and the young person can provide complementary information.","School reports are never relevant to child assessment.","Multi-informant assessment helps clarify functioning across settings."],["Depression in young people can present with irritability as well as low mood.","Children cannot experience clinically significant depression.","Children and adolescents can experience depressive disorders."],["Treatment should be developmentally appropriate and involve caregivers when suitable.","Adult treatment plans should always be copied unchanged for children.","Age, development, preferences and family context matter."],["Suicide and self-harm risk should be asked about directly when indicated.","Young people should never be asked directly about suicide.","Direct, age-appropriate questions are part of safe assessment."],["Learning, sleep, trauma and physical health can affect behaviour and attention.","Every school difficulty is a primary psychiatric disorder.","Differential assessment considers learning and environmental factors."],["Consent, assent and confidentiality should be explained in age-appropriate terms.","Children and adolescents have no role in decisions about their care.","Participation should be supported according to development and law."]]},"older-adults":{"label":"Psychiatry of Older Adults","themes":["Delirium versus dementia and urgent assessment","Depression and suicide risk in later life","Cognition, capacity and medication review","Dementia care, carer support and safety"],"facts":[["Delirium often has acute onset, fluctuating course and impaired attention.","Delirium is usually a stable condition developing gradually over years.","Acute onset and fluctuation are important clues."],["A new acute confusional state warrants assessment for medical causes.","New confusion in an older adult should automatically be diagnosed as dementia.","Delirium and medical precipitants must be considered."],["Dementia assessment considers decline from baseline and functional impact.","A cognitive screening score alone establishes the cause of dementia.","Diagnosis integrates history, function, examination and investigations."],["Depression can affect concentration and mimic or coexist with cognitive impairment.","Depression and dementia can never coexist.","Differential diagnosis and comorbidity should be considered."],["Medication review is important because polypharmacy can contribute to confusion and falls.","Medication effects are irrelevant to cognitive changes in older adults.","Drug effects and interactions may be reversible contributors."],["Capacity is decision-specific and should not be inferred from age alone.","Older age automatically removes decision-making capacity.","Capacity depends on the person and the specific decision."],["Carer strain and safeguarding should be explored when appropriate.","Carer wellbeing has no relevance to dementia care planning.","Carer support can affect safety and sustainability of care."],["Sensory impairment can affect cognitive testing and communication.","Hearing or visual impairment never affects cognitive assessment.","Optimise sensory access for fair assessment."],["Falls, nutrition, driving and home safety may be relevant in dementia care.","Safety planning is unnecessary after a dementia diagnosis.","Care planning should address individual functional risks."],["Delirium prevention includes attention to hydration, orientation and precipitating factors.","Restraint is the universal first-line prevention for delirium.","Non-pharmacological supportive measures are important."]]},"intellectual-disability":{"label":"Intellectual Disability and Learning Disorders","themes":["Intellectual and adaptive-functioning assessment","Communication, behaviour and reasonable adjustments","Coexisting mental illness and diagnostic overshadowing","Individualised care and safeguarding"],"facts":[["Intellectual disability involves limitations in intellectual and adaptive functioning with developmental onset.","An IQ score alone fully describes a person's support needs.","Adaptive functioning and developmental history are also essential."],["Communication should be adapted to the person's abilities and preferences.","Complex jargon is the best way to ensure informed consent.","Accessible communication supports understanding and participation."],["Diagnostic overshadowing occurs when new symptoms are wrongly attributed to disability.","A person with intellectual disability cannot develop depression or psychosis.","Coexisting mental disorders can occur and need assessment."],["Behaviour that challenges may communicate unmet needs or distress.","Challenging behaviour should always be treated as deliberate misconduct.","Pain, communication barriers, environment and distress may contribute."],["Reasonable adjustments improve access to healthcare.","Equal care always means providing identical communication to everyone.","Equitable care adapts to individual needs."],["Physical illness and pain should be considered when behaviour changes.","A sudden behavioural change never warrants physical assessment.","Physical causes can present through behavioural change."],["Care plans should include the person's preferences and support network where appropriate.","The person should be excluded from decisions because they have a disability.","Supported decision-making promotes participation."],["Safeguarding concerns require a proportionate response and appropriate reporting.","Disability removes a person's right to protection from abuse.","People with disabilities may face increased vulnerability and need protection."],["Mental-health assessment may need more time and accessible tools.","Standard interview methods always work equally well for every patient.","Assessment should be adapted to communication and cognitive needs."],["Support needs may vary across domains and environments.","All people with the same diagnostic label need identical support.","Individual strengths, needs and context differ."]]},"eating-sleep":{"label":"Eating and Sleep Disorders","themes":["Eating-disorder assessment and medical risk","Anorexia nervosa, bulimia and binge-eating presentations","Insomnia and behavioural sleep interventions","Parasomnias, sleep disorders and differential diagnosis"],"facts":[["Eating-disorder assessment includes medical stability and nutritional risk.","A normal appearance reliably excludes a serious eating disorder.","Medical risk cannot be judged by appearance alone."],["Anorexia nervosa may involve restriction, fear of weight gain and disturbed body image.","Anorexia nervosa always requires a visibly low body weight before concern is warranted.","Assessment considers the full presentation and medical risk."],["Bulimia nervosa can involve binge eating and compensatory behaviours.","Bulimia nervosa never causes electrolyte disturbance.","Purging can cause serious medical complications."],["Binge-eating disorder involves recurrent binge eating without regular compensatory behaviours characteristic of bulimia.","Binge-eating disorder requires routine vomiting after every episode.","The absence of regular compensatory behaviours helps distinguish it."],["Refeeding risk should be considered in severe malnutrition.","Refeeding syndrome is impossible after prolonged undernutrition.","Metabolic complications can occur during nutritional rehabilitation."],["CBT-based approaches may be used in treatment of insomnia.","Sleep hygiene alone is always sufficient for chronic insomnia.","Chronic insomnia may need structured behavioural treatment."],["Sleep assessment considers substances, medication, mood and medical conditions.","Sleep problems are never associated with psychiatric or physical illness.","Sleep disturbance has a broad differential."],["Daytime impairment and sleep pattern help assess clinical significance.","Sleep duration alone fully defines every sleep disorder.","Timing, quality, symptoms and impairment matter."],["Eating disorders can affect people of any gender and body size.","Eating disorders occur only in one gender and one body type.","Avoid stereotypes and assess symptoms individually."],["Medical instability or significant suicide risk can require urgent escalation.","All eating-disorder presentations are safe for routine outpatient follow-up.","Setting depends on medical and psychiatric risk."]]},"sexual-health":{"label":"Human Sexuality and Gender-Related Presentations","themes":["Respectful sexual history and biopsychosocial assessment","Sexual dysfunction and contributing factors","Consent, capacity, safeguarding and trauma-informed care","Inclusive practice and referral planning"],"facts":[["A sexual history should be relevant, respectful and taken with permission.","A sexual history should be demanded without explaining its relevance.","Permission and a non-judgmental approach support trust."],["Medication, physical illness, mood and relationship factors may affect sexual function.","Sexual dysfunction is always caused by a single psychological factor.","A biopsychosocial assessment considers multiple contributors."],["Consent must be voluntary and can be withdrawn.","Consent once given can never be withdrawn.","Consent is ongoing and specific."],["Confidentiality limits should be explained when safeguarding concerns arise.","Confidentiality can never be limited in any safeguarding situation.","Legal and safety duties may require proportionate disclosure."],["Inclusive language helps patients describe their experiences accurately.","Assumptions about identity or partners improve assessment.","Ask respectfully and avoid assumptions."],["Trauma-informed assessment avoids pressuring a person to disclose details.","A patient must recount every traumatic event before receiving care.","Disclosure should be paced according to safety and readiness."],["Sexual-health concerns can warrant physical examination or investigation when indicated.","A psychiatric formulation means physical causes never need consideration.","Physical and psychological factors can coexist."],["Referral should reflect the patient's goals, risks and relevant expertise.","Referral should be based only on the clinician's personal values.","Care should be evidence-informed and patient-centred."],["Sexual dysfunction can be associated with prescribed medication.","Prescribed medicines cannot affect sexual function.","Medication effects should be reviewed without abrupt unsupervised stopping."],["Capacity and safeguarding should be assessed individually where concerns arise.","A person's diagnosis alone establishes incapacity to consent.","Capacity is decision-specific and context-dependent."]]},"treatments":{"label":"Psychopharmacology and Psychological Treatments","themes":["Psychotropic prescribing and physical-health monitoring","CBT, behavioural and other psychological approaches","ECT, consent and treatment-resistant illness","Adverse effects, interactions and shared decisions"],"facts":[["Prescribing should include indication, expected benefit, risks and monitoring.","Medication can be prescribed safely without reviewing interactions.","Safe prescribing includes relevant interactions and comorbidity."],["Antipsychotic treatment may require metabolic and movement-side-effect monitoring.","Antipsychotics have no metabolic or neurological adverse effects.","Monitoring helps detect clinically important harms."],["Lithium treatment requires appropriate serum and physical-health monitoring.","Lithium has no toxicity risk and requires no blood tests.","Lithium has a narrow therapeutic range and needs monitoring."],["CBT is a collaborative intervention that links thoughts, feelings and behaviour.","CBT requires the therapist to impose beliefs on the patient.","CBT commonly involves collaborative formulation and practice."],["ECT may be considered for selected severe or treatment-resistant presentations.","ECT is never considered in severe psychiatric illness.","ECT may be appropriate after specialist assessment and consent/legal safeguards."],["Medication changes should consider withdrawal and relapse risk.","All psychotropic medication can be stopped abruptly without consequence.","Some medicines require gradual changes and monitoring."],["Shared decision-making includes the patient's goals and preferences.","Patient preference should never influence treatment choice.","Preferences are part of person-centred care."],["Psychological treatment selection should consider evidence, formulation and readiness.","One psychological therapy is equally appropriate for every presentation.","Treatment should be tailored to the problem and patient."],["Adverse effects should be actively reviewed and acted upon.","Reported adverse effects should be ignored if the medicine is effective.","Benefit-risk balance should be reviewed throughout treatment."],["Non-adherence should be explored without blame to identify barriers.","Non-adherence proves that the patient is unwilling to recover.","Barriers can include side effects, beliefs, cost and access."]]},"emergencies":{"label":"Psychiatric Emergencies and Clinical Risk","themes":["Suicide and self-harm risk assessment","Agitation, de-escalation and safe containment","Catatonia, delirium and acute behavioural change","Emergency planning, capacity and follow-up"],"facts":[["Immediate safety and medical causes should be considered in psychiatric emergencies.","A psychiatric label means medical causes can be ignored.","Acute behavioural change may have medical or toxic causes."],["De-escalation begins with calm communication, space and reducing stimulation where safe.","Confrontation and crowding are always the safest first responses to agitation.","A least-restrictive approach can reduce escalation."],["A current suicide plan with intent and access to means requires urgent assessment.","A specific suicide plan never changes urgency.","Plan, intent, means and context can indicate high immediate risk."],["Catatonia can be associated with serious medical complications.","Catatonia is always benign and never needs urgent care.","Prompt recognition and treatment are important."],["Delirium requires evaluation for underlying causes and physiological compromise.","Fluctuating inattention and confusion can be dismissed as ordinary ageing.","Acute fluctuating confusion warrants urgent medical assessment."],["Restrictive interventions should follow law, policy and least-restrictive principles.","Restraint should be used routinely before verbal de-escalation.","Use the least restrictive safe intervention."],["Risk decisions should be documented with rationale and a management plan.","A risk score alone is a complete clinical risk formulation.","Clinical context and a practical plan are essential."],["Collateral information can be vital when immediate risk is difficult to assess.","Collateral information is never useful during emergencies.","Collateral can clarify recent behaviour, means and supports."],["After an emergency, handover and follow-up planning are important.","Care ends once the immediate crisis has settled.","Continuity helps reduce ongoing risk."],["Capacity should be assessed for the specific decision when relevant.","A person in an emergency automatically lacks capacity for every decision.","Capacity is decision-specific and must be assessed appropriately."]]},"forensic-ethics":{"label":"Forensic Psychiatry, Ethics and Mental Health Law","themes":["Capacity, consent and confidentiality","Mental-health law, detention safeguards and rights","Forensic risk assessment and report writing","Ethical dilemmas, boundaries and information sharing"],"facts":[["Capacity assessment is specific to the decision and time.","A psychiatric diagnosis automatically proves incapacity.","Diagnosis alone does not establish inability to decide."],["Confidentiality may have limits when disclosure is legally required or needed to prevent serious harm.","Confidentiality has no exceptions under any circumstances.","Limits depend on law, professional duties and risk."],["Legal criteria for involuntary assessment or detention vary by jurisdiction.","One universal detention rule applies identically in every country.","Local legislation and procedures must be followed."],["Forensic reports should distinguish observed facts, collateral information and opinion.","A forensic report should present assumptions as established facts.","Transparent evidence and reasoning are essential."],["Risk assessment considers history, current factors and protective factors.","Risk prediction is perfectly certain in every individual.","Risk assessments have uncertainty and should guide management."],["Consent should be informed and voluntary when the person has relevant capacity.","Consent is valid even when obtained through coercion.","Voluntariness and understanding matter."],["Information sharing should be proportionate and documented.","Any concern justifies sharing all confidential information with anyone.","Share only what is justified and necessary."],["Professional boundaries protect patients and clinicians.","Boundary violations are harmless if intentions are good.","Boundaries support safety and trust."],["Patients retain dignity and rights during involuntary care.","Involuntary care removes every patient right.","Legal safeguards and rights continue to apply."],["Cultural and social context should be considered without stereotyping.","Cultural difference alone proves mental disorder.","Assessment should avoid cultural bias."]]},"liaison-misc":{"label":"Liaison Psychiatry and Miscellaneous Topics","themes":["Psychiatric symptoms in physical illness","Somatic symptoms, health anxiety and coordinated care","Consultation-liaison assessment and capacity","Biopsychosocial formulation and discharge planning"],"facts":[["Psychiatric and physical disorders can coexist and influence each other.","A physical illness excludes a coexisting psychiatric disorder.","Integrated assessment considers both."],["New confusion in hospital requires consideration of delirium and medical causes.","Hospital confusion should automatically be labelled a primary psychiatric illness.","Acute confusion may reflect physiological illness or medication effects."],["Medication review is important when symptoms begin after a treatment change.","Medication timing is never relevant to new psychiatric symptoms.","Drug effects and interactions may contribute."],["A biopsychosocial formulation considers biological, psychological and social contributors.","A biopsychosocial formulation excludes physical examination.","All three domains can be relevant."],["Liaison assessment should clarify the referral question and urgency.","The referral question is irrelevant to consultation-liaison work.","Clarifying the question helps focus assessment and recommendations."],["Health anxiety should be assessed respectfully while avoiding unnecessary reinforcement of unhelpful cycles.","Health anxiety means the patient's symptoms should be mocked or dismissed.","Validation and coordinated care are important."],["Capacity may need assessment for a specific medical decision.","Capacity is determined only by the presence of mental illness.","Decision-specific assessment is required."],["Discharge planning should include follow-up, medication and warning signs when relevant.","Discharge plans do not need to communicate risks or follow-up.","Clear plans support continuity and safety."],["Pain, sleep disruption and substance use may affect mental state.","Pain and sleep never affect mood or cognition.","Physical symptoms and context can affect psychiatric presentation."],["Communication between medical and mental-health teams supports safer care.","Interdisciplinary communication is unnecessary in complex cases.","Coordinated recommendations reduce fragmented care."]]}};
const base=window.PSYCHIATRY_MODULE_BANKS;
for(const [id,c] of Object.entries(configs)){
 const b=base[id]; if(!b) throw new Error('Missing module '+id); b.label=c.label;
 const facts=c.facts;
 const statements=[];
 facts.forEach((f,i)=>{statements.push([f[0],true,f[2]]);statements.push([f[1],false,f[2]+' The statement is false.']);});
 while(statements.length<30){const f=facts[statements.length%facts.length];statements.push([f[0],true,f[2]]);}
 const groups=[]; for(let i=0;i<30;i+=5) groups.push({title:'Core concepts '+(i/5+1),category:c.label,statements:statements.slice(i,i+5)}); b.tf=groups;
 const sbas=[]; for(let i=0;i<30;i++){const f=facts[i%facts.length];const variant=Math.floor(i/facts.length);const stem=variant===0?('Which statement is most accurate regarding '+f[0].replace(/[.!?]$/,'').toLowerCase()+'?'):variant===1?('In a clinical assessment, which principle should guide the clinician when considering: '+f[0].replace(/[.!?]$/,'').toLowerCase()+'?'):('Which option best reflects safe, evidence-informed practice concerning '+f[0].replace(/[.!?]$/,'').toLowerCase()+'?'); const wrong=[f[1],...sharedDistractors].slice(0,4); const opts=[f[0],...wrong]; const letters=['A','B','C','D','E']; const shift=(i+variant)%5; const shuffled=opts.map((v,j)=>({v,correct:j===0})).sort((a,z)=>((opts.indexOf(a.v)+shift)%5)-((opts.indexOf(z.v)+shift)%5));const options={};let answer='A';shuffled.forEach((x,j)=>{options[letters[j]]=x.v;if(x.correct)answer=letters[j];});sbas.push({title:'Applied knowledge '+String(i+1).padStart(2,'0'),category:c.label,stem,options,answer,explanation:f[2]+' The other options either contradict this principle or omit essential assessment and management considerations.'}); } b.sba=sbas;
 b.essays=c.themes.map((theme,i)=>({title:'Essay '+(i+1)+': '+theme,category:c.label,prompt:'Discuss '+theme.toLowerCase()+'. Include definition or clinical framing, assessment, differential diagnosis and risk, investigations where indicated, management, and follow-up.',max:20,modelAnswer:'A strong answer on '+theme.toLowerCase()+' should establish the clinical problem and time course; obtain relevant psychiatric, medical, medication, substance, developmental and social history; perform an appropriate mental state and physical/cognitive assessment; consider important differentials and red flags; assess risk and protective factors; select proportionate, evidence-informed treatment through shared decision-making; document the rationale, safety plan and follow-up; and adapt the plan to the patient’s needs and local guidance.',rubric:[{label:'Clinical framing, history and formulation',points:5,feedback:'Define the presentation and cover chronology, relevant history, function and a coherent biopsychosocial formulation.',groups:[['definition','presentation'],['history','chronology'],['function','formulation']]},{label:'Examination, differential and risk',points:5,feedback:'Include relevant mental state/physical or cognitive examination, key differential diagnoses, red flags and risk/protective factors.',groups:[['examination','mental state'],['differential','investigations'],['risk','protective factors']]},{label:'Management and justification',points:5,feedback:'Give a safe, evidence-informed, individualised plan, including urgent steps where indicated and rationale for interventions.',groups:[['management','treatment'],['safety','urgent'],['rationale','shared decision']]},{label:'Communication, continuity and follow-up',points:5,feedback:'Address consent, documentation, relevant family/team involvement, prevention or relapse planning and specific follow-up.',groups:[['consent','communication'],['documentation','team'],['follow up','relapse','prevention']]}]}));
}
})();
